CREATE TRIGGER UNDGSubstance_Version_Create
	ON UNDGSubstance
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT DG_PK, 'DG'
	FROM inserted
GO
CREATE TRIGGER UNDGSubstance_Version_Update
	ON UNDGSubstance
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON DG_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER UNDGSubstance_DataChangeHistory
	ON UNDGSubstance
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT DG_PK, 'DG' FROM inserted
	UNION
	SELECT DG_PK, 'DG' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER UNDGSubstance_DataProcessingResult_Delete
	ON UNDGSubstance
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.DG_PK
	END
GO
